package cl.bolsillo.app;
import android.animation.*;import android.view.*;import android.view.animation.PathInterpolator;import java.util.*;
/** Material motion on a bounded viewport, with one owner and deterministic cancellation. */
final class PageMotion {
 static final android.view.animation.Interpolator EASE=new PathInterpolator(.2f,0f,0f,1f);
 static final WeakHashMap<View,ViewTreeObserver.OnPreDrawListener> pending=new WeakHashMap<>();
 static final WeakHashMap<View,Animator> animations=new WeakHashMap<>();
 static View viewport(View content){return content.getParent() instanceof android.widget.ScrollView?(View)content.getParent():content;}
 static boolean running(View source){if(animations.containsKey(source)||pending.containsKey(source))return true;if(source instanceof ViewGroup&&((ViewGroup)source).getChildCount()>0)return animations.containsKey(((ViewGroup)source).getChildAt(0))||pending.containsKey(((ViewGroup)source).getChildAt(0));return false;}
 static void neutral(View view){view.setTranslationX(0);view.setTranslationY(0);view.setAlpha(1);view.setScaleX(1);view.setScaleY(1);view.setLayerType(View.LAYER_TYPE_NONE,null);}
 static void reset(View view){ViewTreeObserver.OnPreDrawListener old=pending.remove(view);if(old!=null&&view.getViewTreeObserver().isAlive())view.getViewTreeObserver().removeOnPreDrawListener(old);Animator animation=animations.remove(view);if(animation!=null)animation.cancel();view.animate().withEndAction(null).cancel();neutral(view);neutral(viewport(view));}
 static void start(View key,View target,Animator animation){if(target instanceof android.widget.ScrollView)target.setLayerType(View.LAYER_TYPE_HARDWARE,null);animations.put(key,animation);animation.addListener(new AnimatorListenerAdapter(){@Override public void onAnimationEnd(Animator a){if(animations.get(key)==a){animations.remove(key);neutral(target);}}});animation.start();}
 static void enter(View view,int direction){reset(view);if(!ValueAnimator.areAnimatorsEnabled())return;final ViewTreeObserver.OnPreDrawListener[] listener=new ViewTreeObserver.OnPreDrawListener[1];listener[0]=()->{if(view.getViewTreeObserver().isAlive())view.getViewTreeObserver().removeOnPreDrawListener(listener[0]);if(pending.get(view)!=listener[0])return true;pending.remove(view);if(view.isAttachedToWindow()){boolean section=view.getContext() instanceof MainActivity&&Arrays.asList("Inicio","Movimientos","Cuentas","Explorar").contains(((MainActivity)view.getContext()).tab);View target=viewport(view);start(view,target,MaterialMotion.appear(target,section,direction));}return true;};pending.put(view,listener[0]);view.getViewTreeObserver().addOnPreDrawListener(listener[0]);view.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){}public void onViewDetachedFromWindow(View v){reset(v);v.removeOnAttachStateChangeListener(this);}});}
 static void settle(View view){float from=view.getTranslationX();reset(view);if(ValueAnimator.areAnimatorsEnabled()&&from!=0){ObjectAnimator animation=ObjectAnimator.ofFloat(view,View.TRANSLATION_X,from,0);animation.setDuration(150);animation.setInterpolator(EASE);start(view,view,animation);}}
}
